CREATE OR REPLACE FUNCTION public.mark_autores_resumen_dirty_on_obra()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (new.visible_publico is distinct from old.visible_publico)
     or (new.estado is distinct from old.estado) then
    update public.autores_resumen
    set metrica_sucia = true
    where autor_id in (
      select distinct u.autor_id
      from public.perfil_metrico_unidades() u
      where u.obra_id = new.obra_id
    );
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_obra_resumen_dirty_by_cuadro()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_jornada_id uuid;
  v_obra_id uuid;
begin
  for v_jornada_id in
    select distinct jornada_id
    from (
      values
        (case when tg_op <> 'INSERT' then old.jornada_id else null end),
        (case when tg_op <> 'DELETE' then new.jornada_id else null end)
    ) as ids(jornada_id)
    where jornada_id is not null
  loop
    select j.obra_id
    into v_obra_id
    from public.jornadas j
    where j.jornada_id = v_jornada_id;

    if v_obra_id is not null then
      update public.obras_resumen
      set metrica_sucia = true
      where obra_id = v_obra_id;
    end if;
  end loop;

  return coalesce(new, old);
end;
$function$

