CREATE OR REPLACE FUNCTION public.obra_declara_por_sus_secuencias()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
	-- **Marcar es responder por las secuencias que callaban**, no borrar lo que dicen. Por eso
	-- primero se comprueba que ninguna diga lo contrario, y solo entonces se rellenan los huecos.
	if new.sin_figuras_donaire then
		if exists (
			select 1 from public.secuencias_metricas sm
			where sm.obra_id = new.obra_id
			  and sm.intervencion_figuras_donaire in ('exclusiva', 'compartida')
		) then
			raise exception 'Alguna secuencia declara la intervención de una figura de donaire: quítala antes de marcar que la obra no las tiene.'
				using errcode = 'check_violation';
		end if;
		update public.secuencias_metricas
		set intervencion_figuras_donaire = 'sin_intervencion'
		where obra_id = new.obra_id and intervencion_figuras_donaire is null;
	end if;

	if new.sin_personajes_sobrenaturales then
		if exists (
			select 1 from public.secuencias_metricas sm
			where sm.obra_id = new.obra_id
			  and sm.intervencion_personajes_sobrenaturales in ('exclusiva', 'compartida')
		) then
			raise exception 'Alguna secuencia declara la intervención de un personaje sobrenatural: quítala antes de marcar que la obra no los tiene.'
				using errcode = 'check_violation';
		end if;
		update public.secuencias_metricas
		set intervencion_personajes_sobrenaturales = 'sin_intervencion'
		where obra_id = new.obra_id and intervencion_personajes_sobrenaturales is null;
	end if;

	if new.sin_eventos_sobrenaturales then
		if exists (
			select 1 from public.secuencias_metricas sm
			where sm.obra_id = new.obra_id and sm.evento_sobrenatural
		) then
			raise exception 'Alguna secuencia declara un evento sobrenatural: quítalo antes de marcar que la obra no los tiene.'
				using errcode = 'check_violation';
		end if;
		update public.secuencias_metricas
		set evento_sobrenatural = false
		where obra_id = new.obra_id and evento_sobrenatural is null;
	end if;

	return new;
end
$function$

CREATE OR REPLACE FUNCTION public.obra_recuerda_su_publicacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
	-- Una vez puesta no se mueve, la escriba quien la escriba.
	if tg_op = 'UPDATE' and old.fecha_publicacion is not null then
		new.fecha_publicacion := old.fecha_publicacion;
		return new;
	end if;

	if new.fecha_publicacion is null and exists (
		select 1
		from public.vocabularios estado
		where estado.termino_id = new.estado
			and estado.categoria = 'estado'
			and lower(estado.termino) = 'publicado'
	) then
		new.fecha_publicacion := now();
	end if;

	return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.obras_enforce_public_visibility()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
	v_publicado_id uuid;
begin
	select termino_id
	into v_publicado_id
	from public.vocabularios
	where categoria = 'estado'
		and lower(termino) = 'publicado'
	limit 1;

	if v_publicado_id is null then
		raise exception 'No existe estado=publicado en vocabularios';
	end if;

	if coalesce(new.visible_publico, false)
		and new.estado is distinct from v_publicado_id then
		raise exception using
			errcode = '23514',
			message = 'visible_publico solo puede activarse cuando la obra esta en estado publicado';
	end if;

	if tg_op = 'UPDATE'
		and old.estado = v_publicado_id
		and new.estado is distinct from v_publicado_id then
		new.visible_publico := false;
	end if;

	return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.perfil_artefacto_obra_rango(p_obra_id uuid, p_v_ini integer DEFAULT NULL::integer, p_v_fin integer DEFAULT NULL::integer, p_nivel text DEFAULT 'forma'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
	v_payload jsonb;
	v_perfil jsonb;
begin
	if p_nivel not in ('forma', 'arquitectura') then
		raise exception 'Nivel de perfil desconocido: %', p_nivel;
	end if;

	select payload into v_payload
	from public.artefactos_publicos
	where clave = format('obras/%s/analisis/publico.json', p_obra_id)
		and not sucio;

	if v_payload is null then
		if p_nivel = 'forma' then
			return public.perfil_formas_rango(p_obra_id, p_v_ini, p_v_fin);
		end if;
		return public.perfil_formas_hijos_rango(p_obra_id, p_v_ini, p_v_fin);
	end if;

	select coalesce(jsonb_object_agg(clave, versos), '{}'::jsonb)
	into v_perfil
	from (
		select
			case
				when p_nivel = 'forma' then s.value ->> 'forma'
				else concat_ws('/', s.value ->> 'forma', s.value ->> 'arquitectura')
			end as clave,
			sum(coalesce((s.value ->> 'n')::integer, 0))::integer as versos
		from jsonb_array_elements(coalesce(v_payload -> 'secuencias', '[]'::jsonb)) s(value)
		where (p_v_ini is null or (s.value ->> 'i')::integer >= p_v_ini)
			and (p_v_fin is null or (s.value ->> 'f')::integer <= p_v_fin)
			and s.value ->> 'forma' is not null
			and (p_nivel = 'forma' or s.value ->> 'arquitectura' is not null)
		group by 1
	) perfiles
	where clave is not null and clave <> '';

	return coalesce(v_perfil, '{}'::jsonb);
end;
$function$

CREATE OR REPLACE FUNCTION public.plan_recompute_datos_publicos()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
	v_publicado_id uuid;
	v_obras jsonb;
	v_autores jsonb;
begin
	if not public.auth_is_admin_or_ip() then
		raise exception 'Solo admin o IP pueden planificar el recálculo público'
			using errcode = '42501';
	end if;

	select termino_id
	into v_publicado_id
	from public.vocabularios
	where categoria = 'estado'
		and lower(termino) = 'publicado'
	limit 1;

	if v_publicado_id is null then
		raise exception 'No existe estado=publicado en vocabularios';
	end if;

	select coalesce(
		jsonb_agg(
			jsonb_build_object('id', obra.obra_id, 'titulo', obra.titulo)
			order by lower(obra.titulo), obra.obra_id
		),
		'[]'::jsonb
	)
	into v_obras
	from public.obras obra
	where obra.estado = v_publicado_id;

	select coalesce(
		jsonb_agg(
			jsonb_build_object('id', autor.autor_id, 'nombre', autor.nombre_completo)
			order by lower(autor.nombre_completo), autor.autor_id
		),
		'[]'::jsonb
	)
	into v_autores
	from (
		select distinct a.autor_id, a.nombre_completo
		from public.perfil_metrico_unidades() unidad
		join public.autores a on a.autor_id = unidad.autor_id
		where unidad.autor_id is not null
	) autor;

	return jsonb_build_object('obras', v_obras, 'autores', v_autores);
end;
$function$

CREATE OR REPLACE FUNCTION public.recompute_artefactos_autor(p_autor_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
	v_alcance text;
	v_payload jsonb;
begin
	foreach v_alcance in array array['publico', 'completo'] loop
		v_payload := public.autor_ficha_artefacto_json(p_autor_id, v_alcance);
		if v_payload is not null then
			perform public.guardar_artefacto_publico(
				format('autores/%s/ficha/%s.json', p_autor_id, v_alcance),
				'autor_ficha', p_autor_id, v_alcance, v_payload, 1
			);
		end if;
	end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.recompute_artefactos_obra(p_obra_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
	v_ficha jsonb;
	v_analisis jsonb;
begin
	select ficha into v_ficha from public.obras_resumen where obra_id = p_obra_id;
	if v_ficha is null then
		raise exception 'La obra % no tiene ficha precomputada', p_obra_id;
	end if;

	v_analisis := public.analisis_obra_publico_json(p_obra_id);
	perform public.guardar_artefacto_publico(
		format('obras/%s/ficha/publico.json', p_obra_id),
		'obra_ficha', p_obra_id, 'publico',
		jsonb_build_object('schema_version', 1, 'ficha', v_ficha), 1
	);
	perform public.guardar_artefacto_publico(
		format('obras/%s/analisis/publico.json', p_obra_id),
		'obra_analisis', p_obra_id, 'publico', v_analisis, 2
	);
end;
$function$

CREATE OR REPLACE FUNCTION public.secuencia_respeta_lo_declarado_en_la_obra()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
	v_obra public.obras%rowtype;
begin
	select * into v_obra from public.obras where obra_id = new.obra_id;
	if not found then
		return new;
	end if;

	if v_obra.sin_figuras_donaire
	   and new.intervencion_figuras_donaire in ('exclusiva', 'compartida') then
		raise exception 'La obra está marcada como que no tiene figuras de donaire: quita la marca antes de anotarlo en la secuencia.'
			using errcode = 'check_violation';
	end if;

	if v_obra.sin_personajes_sobrenaturales
	   and new.intervencion_personajes_sobrenaturales in ('exclusiva', 'compartida') then
		raise exception 'La obra está marcada como que no tiene personajes sobrenaturales: quita la marca antes de anotarlo en la secuencia.'
			using errcode = 'check_violation';
	end if;

	if v_obra.sin_eventos_sobrenaturales and new.evento_sobrenatural then
		raise exception 'La obra está marcada como que no tiene eventos sobrenaturales: quita la marca antes de anotarlo en la secuencia.'
			using errcode = 'check_violation';
	end if;

	return new;
end
$function$

CREATE OR REPLACE FUNCTION public.set_obras_slug()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
	v_old_base text;
begin
	if tg_op = 'INSERT' then
		if new.slug is null or btrim(new.slug) = '' then
			new.slug := public.next_obras_slug(new.titulo, new.obra_id);
		else
			new.slug := coalesce(nullif(public.metadrama_slugify(new.slug), ''), 'obra');
		end if;
		return new;
	end if;

	if new.slug is null or btrim(new.slug) = '' then
		new.slug := public.next_obras_slug(new.titulo, new.obra_id);
		return new;
	end if;

	if new.slug is distinct from old.slug then
		new.slug := coalesce(nullif(public.metadrama_slugify(new.slug), ''), 'obra');
		return new;
	end if;

	if new.titulo is distinct from old.titulo then
		v_old_base := coalesce(nullif(public.metadrama_slugify(old.titulo), ''), 'obra');
		if old.slug ~ ('^' || v_old_base || '(-[0-9]+)?$') then
			new.slug := public.next_obras_slug(new.titulo, new.obra_id);
		else
			new.slug := coalesce(nullif(public.metadrama_slugify(new.slug), ''), 'obra');
		end if;
	else
		new.slug := coalesce(nullif(public.metadrama_slugify(new.slug), ''), 'obra');
	end if;

	return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sincronizar_generos_intervinientes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.generos_intervinientes is null then
      new.generos_intervinientes := public.generos_desde_intervencion_femenina(new.intervencion_personajes_femeninos);
    end if;
  elsif new.generos_intervinientes is not distinct from old.generos_intervinientes
    and new.intervencion_personajes_femeninos is distinct from old.intervencion_personajes_femeninos then
    new.generos_intervinientes := public.generos_desde_intervencion_femenina(new.intervencion_personajes_femeninos);
  end if;
  if new.generos_intervinientes is not null then
    if not public.generos_intervinientes_validos(new.generos_intervinientes) then
      raise exception 'Selecciona de uno a tres géneros diferentes: masculino, femenino, indeterminado'
        using errcode = '23514';
    end if;
    -- Orden estable, independiente del orden de los clics.
    select array_agg(valor order by posicion) into new.generos_intervinientes
    from unnest(array['masculino','femenino','indeterminado']) with ordinality g(valor,posicion)
    where valor = any(new.generos_intervinientes);
  end if;
  new.intervencion_personajes_femeninos := public.intervencion_femenina_desde_generos(new.generos_intervinientes);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_obra_autor_ficha_publico()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
	if new.editor_asignado is null then
		new.autor_ficha_publico := null;
		return new;
	end if;

	select e.nombre_completo
	into new.autor_ficha_publico
	from public.editores e
	where e.user_id = new.editor_asignado
	limit 1;

	return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validar_anotacion_desviacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
	v_secuencia_ini integer;
	v_secuencia_fin integer;
	v_configuracion_id uuid;
begin
	select v_ini, v_fin, arquitectura_id
	into v_secuencia_ini, v_secuencia_fin, v_configuracion_id
	from public.anotaciones_metricas
	where anotacion_id = new.anotacion_id;

	if v_configuracion_id is null then
		raise exception 'Una tramo sin forma no admite desviaciones respecto de una norma inexistente';
	end if;
	if new.v_ini < v_secuencia_ini or new.v_fin > v_secuencia_fin then
		raise exception 'La desviación debe quedar dentro del rango de la secuencia';
	end if;
	if new.realizacion_id is not null and not exists (
		select 1 from public.anotacion_realizaciones
		where realizacion_id = new.realizacion_id
			and anotacion_id = new.anotacion_id
	) then
		raise exception 'La unidad de la desviación no pertenece a la secuencia';
	end if;
	return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validar_anotacion_eleccion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
	v_arquitectura uuid;
	v_seccion_unidad uuid;
	v_padre uuid;
	v_longitud integer;
	v_entidades integer;
	v_escrito integer;
	v_admitida boolean;
	v_control text;
	v_medidas text[];
begin
	select arquitectura_id, v_fin - v_ini + 1
	into v_arquitectura, v_longitud
	from public.anotaciones_metricas
	where anotacion_id = new.anotacion_id;

	v_entidades := num_nonnulls(
		new.metro_id, new.esquema_metrico_id, new.esquema_rima_id, new.seccion_id,
		new.repeticion_id, new.valor_rasgo_id, new.variedad_id
	);

	if v_entidades = 0 and new.valor_texto is null then
		raise exception 'Una respuesta sin dato no se guarda';
	end if;

	if new.realizacion_id is not null then
		select seccion_id, realizacion_padre_id, v_fin - v_ini + 1
		into v_seccion_unidad, v_padre, v_longitud
		from public.anotacion_realizaciones
		where realizacion_id = new.realizacion_id and anotacion_id = new.anotacion_id;

		if not found then
			raise exception 'La unidad no pertenece a la secuencia';
		end if;
	end if;

	-- Un tramo sin forma no declara arquitectura: su respuesta se sostiene sola.
	if v_arquitectura is null then
		return new;
	end if;

	if v_entidades = 1 then
		-- ¿La ofrece el catálogo? Se busca entre las preguntas de la arquitectura, **heredadas
		-- incluidas**: ya no hace falta preguntar aparte por lo que la parte reutiliza.
		select exists (
			select 1
			from public.opciones_eleccion_metrica o
			join public.preguntas_metricas g on g.grupo_eleccion_id = o.grupo_eleccion_id
			where g.activo
				and g.arquitectura_id = v_arquitectura
				and g.dimension = new.dimension
				and g.seccion_tratada_id is not distinct from new.seccion_tratada_id
				and g.seccion_id is not distinct from (
					case when v_padre is not null then v_seccion_unidad end
				)
				and o.metro_id is not distinct from new.metro_id
				and o.esquema_metrico_id is not distinct from new.esquema_metrico_id
				and o.esquema_rima_id is not distinct from new.esquema_rima_id
				and o.seccion_id is not distinct from new.seccion_id
				and o.repeticion_id is not distinct from new.repeticion_id
				and o.valor_rasgo_id is not distinct from new.valor_rasgo_id
				and o.variedad_id is not distinct from new.variedad_id
				and o.posicion_unidad is not distinct from new.posicion_unidad
		) into v_admitida;

		if not v_admitida then
			raise exception 'La respuesta no está admitida por la norma de esta arquitectura en la dimensión %', new.dimension;
		end if;
	else
		-- **Qué se ha escrito lo dice el control de la pregunta**, no la dimensión: una notación de
		-- rima se lee letra a letra y una serie de medidas, número a número.
		select g.tipo_control
		into v_control
		from public.preguntas_metricas g
		where g.activo
			and g.arquitectura_id = v_arquitectura
			and g.dimension = new.dimension
			and g.tipo_control in ('esquema_rima', 'opciones_y_esquema', 'serie_medidas')
			and g.seccion_tratada_id is not distinct from new.seccion_tratada_id
			and g.seccion_id is not distinct from (
				case when v_padre is not null then v_seccion_unidad end
			)
		limit 1;

		if v_control is null then
			raise exception 'Esta arquitectura no admite escribir la respuesta en la dimensión %', new.dimension;
		end if;

		if v_control = 'serie_medidas' then
			-- Una medida por verso, separadas por espacios: `11 7 11 11 7`.
			v_medidas := regexp_split_to_array(btrim(new.valor_texto), '\s+');
			if exists (select 1 from unnest(v_medidas) medida where medida !~ '^[0-9]{1,2}$') then
				raise exception 'La serie de medidas solo admite números de una o dos cifras, y trae «%»', new.valor_texto;
			end if;
			v_escrito := coalesce(array_length(v_medidas, 1), 0);
			if v_longitud is not null and v_escrito <> v_longitud then
				raise exception 'La serie debe traer % medidas, una por verso, y trae %', v_longitud, v_escrito;
			end if;
		else
			-- Una notación se lee verso a verso. Se descuentan los separadores que la propia notación
			-- trae —`abcabc|defdef`, `abba:cdcd`— y los espacios.
			v_escrito := length(regexp_replace(new.valor_texto, '[:|[:space:]]', '', 'g'));
			if v_longitud is not null and v_escrito <> v_longitud then
				raise exception 'El esquema de rima debe tener % posiciones y tiene %', v_longitud, v_escrito;
			end if;
		end if;
	end if;

	return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validar_anotacion_metrica()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
	v_tipo_registro text;
	v_slug text;
begin
	select tipo_registro, slug
	into v_tipo_registro, v_slug
	from public.formas_metricas
	where forma_id = new.forma_id
		and activo;

	if v_tipo_registro is null then
		raise exception 'La entrada métrica no está activa';
	end if;

	if v_tipo_registro = 'sin_forma' then
		-- **Un tramo sí admite arquitectura**, siempre que sea suya. Lo que no admite es que esa
		-- arquitectura declare norma, y de eso se encargan las guardas del catálogo.
		if new.arquitectura_id is not null and not exists (
			select 1
			from public.arquitecturas_forma configuracion
			where configuracion.arquitectura_id = new.arquitectura_id
				and configuracion.forma_id = new.forma_id
				and configuracion.activo
		) then
			raise exception 'La arquitectura no pertenece a este tramo';
		end if;
		if v_slug = 'verso_aislado' and new.v_fin <> new.v_ini then
			raise exception 'Verso aislado debe abarcar exactamente un verso';
		end if;
		if v_slug = 'irregular' and new.v_fin - new.v_ini + 1 < 2 then
			raise exception 'Versificación irregular debe abarcar al menos dos versos';
		end if;
		return new;
	end if;

	if new.arquitectura_id is null or not exists (
		select 1
		from public.arquitecturas_forma configuracion
		where configuracion.arquitectura_id = new.arquitectura_id
			and configuracion.forma_id = new.forma_id
			and configuracion.activo
	) then
		raise exception 'La arquitectura no pertenece a una forma activa';
	end if;

	return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validar_anotacion_realizacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
	declare
		v_arquitectura_id uuid;
		v_arquitectura_unidad uuid;
		v_arquitectura_efectiva uuid;
		v_secuencia_ini integer;
		v_secuencia_fin integer;
		v_seccion_padre_esperada uuid;
		v_seccion_padre_real uuid;
		v_padre_ini integer;
		v_padre_fin integer;
	begin
		select arquitectura_id, v_ini, v_fin
		into v_arquitectura_id, v_secuencia_ini, v_secuencia_fin
		from public.anotaciones_metricas
		where anotacion_id = new.anotacion_id;

		if new.v_ini < v_secuencia_ini or new.v_fin > v_secuencia_fin then
			raise exception 'La realización debe quedar dentro del rango de la secuencia';
		end if;

		-- Una realización sin sección es la realización de la unidad que define la forma.
		if new.seccion_id is null then
			if new.realizacion_padre_id is not null then
				raise exception 'La realización de la unidad no cuelga de ninguna otra';
			end if;
			return new;
		end if;

		if new.realizacion_padre_id is null then
			raise exception 'Una sección se realiza siempre dentro de una unidad';
		end if;

		-- **La arquitectura de la unidad de la que cuelga esta sección.** Se sube por la cadena
		-- hasta la realización sin padre, que es la de la unidad. Casi siempre no declara nada y
		-- manda la de la secuencia; cuando declara una intercalada, manda la suya.
		with recursive cadena as (
			select realizacion_id, realizacion_padre_id, arquitectura_id
			from public.anotacion_realizaciones
			where realizacion_id = new.realizacion_padre_id
				and anotacion_id = new.anotacion_id
			union all
			select superior.realizacion_id,
				superior.realizacion_padre_id,
				superior.arquitectura_id
			from public.anotacion_realizaciones superior
			join cadena on cadena.realizacion_padre_id = superior.realizacion_id
			where superior.anotacion_id = new.anotacion_id
		)
		select arquitectura_id into v_arquitectura_unidad
		from cadena
		where realizacion_padre_id is null;

		v_arquitectura_efectiva := coalesce(v_arquitectura_unidad, v_arquitectura_id);

		select seccion_padre_id
		into v_seccion_padre_esperada
		from public.estructuras_secciones
		where seccion_id = new.seccion_id
			and arquitectura_id = v_arquitectura_efectiva;

		if not found then
			raise exception 'La sección realizada no pertenece a la arquitectura seleccionada';
		end if;

		select seccion_id, v_ini, v_fin
		into v_seccion_padre_real, v_padre_ini, v_padre_fin
		from public.anotacion_realizaciones
		where realizacion_id = new.realizacion_padre_id
			and anotacion_id = new.anotacion_id;

		if not found then
			raise exception 'La realización superior debe pertenecer a la misma secuencia';
		end if;
		-- Una sección raíz cuelga de la unidad, cuya realización no tiene sección; una sección
		-- interna cuelga de la realización de su sección superior.
		if v_seccion_padre_real is distinct from v_seccion_padre_esperada then
			raise exception 'La realización superior no corresponde a la jerarquía de la sección';
		end if;
		if new.v_ini < v_padre_ini or new.v_fin > v_padre_fin then
			raise exception 'La sección interna debe quedar dentro del rango de su unidad';
		end if;

		return new;
	end;
	$function$

CREATE OR REPLACE FUNCTION public.validar_arquitectura_de_realizacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
	declare
		v_forma_secuencia uuid;
		v_forma_excepcion uuid;
		v_intercalable boolean;
	begin
		if new.arquitectura_id is null then
			return new;
		end if;

		-- Una excepción es de la unidad, no de una parte suya: una sección no cambia de
		-- arquitectura, cambia la estrofa entera.
		if new.realizacion_padre_id is not null or new.seccion_id is not null then
			raise exception 'Solo una unidad completa puede declarar otra arquitectura, no una de sus partes';
		end if;

		select a.forma_id into v_forma_secuencia
		from public.anotaciones_metricas s
		join public.arquitecturas_forma a on a.arquitectura_id = s.arquitectura_id
		where s.anotacion_id = new.anotacion_id;

		select forma_id, intercalable into v_forma_excepcion, v_intercalable
		from public.arquitecturas_forma
		where arquitectura_id = new.arquitectura_id;

		if v_forma_secuencia is null then
			raise exception 'La secuencia no declara arquitectura: no hay de qué ser excepción';
		end if;
		if v_forma_excepcion is distinct from v_forma_secuencia then
			raise exception 'Una realización solo puede declarar otra arquitectura de su misma forma';
		end if;
		if not coalesce(v_intercalable, false) then
			raise exception 'Esa arquitectura no está declarada intercalable en el catálogo';
		end if;

		return new;
	end;
	$function$

CREATE OR REPLACE FUNCTION public.validar_estructura_anotacion_diferida()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
	perform public.validar_estructura_anotacion(
		case when tg_op = 'DELETE' then old.anotacion_id else new.anotacion_id end
	);
	return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.validar_extension_patron_anotacion_realizaciones()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
	v_secuencia_id uuid := coalesce(new.anotacion_id, old.anotacion_id);
	v_incompatibles integer;
begin
	select count(*)
	into v_incompatibles
	from (
		select r.seccion_id, r.realizacion_padre_id
		from public.anotacion_realizaciones r
		join public.estructuras_secciones s on s.seccion_id = r.seccion_id
		where r.anotacion_id = v_secuencia_id
			and s.primera_realizacion_define_patron
		group by r.seccion_id, r.realizacion_padre_id
		having count(distinct (r.v_fin - r.v_ini + 1)) > 1
	) discrepancias;

	if v_incompatibles > 0 then
		raise exception 'Las realizaciones cuyo patrón declara la primera deben tener la misma extensión';
	end if;

	return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.validar_posicion_anotacion_eleccion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
	v_versos integer;
	v_repetida integer;
begin
	if new.posicion_unidad is null or new.realizacion_id is null then
		return new;
	end if;

	select v_fin - v_ini + 1 into v_versos
	from public.anotacion_realizaciones
	where realizacion_id = new.realizacion_id;

	if v_versos is not null and new.posicion_unidad > v_versos then
		raise exception
			'La posición % no existe: la realización tiene % versos',
			new.posicion_unidad, v_versos;
	end if;

	select count(*) into v_repetida
	from public.anotacion_elecciones eleccion
	where eleccion.realizacion_id = new.realizacion_id
		and eleccion.dimension = new.dimension
		and eleccion.seccion_tratada_id is not distinct from new.seccion_tratada_id
		and eleccion.eleccion_id is distinct from new.eleccion_id
		and eleccion.posicion_unidad = new.posicion_unidad;

	if v_repetida > 0 then
		raise exception 'Ya hay una respuesta para la posición %', new.posicion_unidad;
	end if;

	return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_atribucion_vocab_refs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
	v_tipo_categoria text;
	v_modalidad_categoria text;
	v_composicion_categoria text;
begin
	select categoria into v_tipo_categoria
	from public.vocabularios
	where termino_id = new.tipo_atribucion_id;

	if v_tipo_categoria is distinct from 'tipo_atribucion' then
		raise exception using
			errcode = '23514',
			message = 'tipo_atribucion_id debe apuntar a vocabularios.categoria=tipo_atribucion';
	end if;

	select categoria into v_modalidad_categoria
	from public.vocabularios
	where termino_id = new.modalidad_atribucion_id;

	if v_modalidad_categoria is distinct from 'modalidad_atribucion' then
		raise exception using
			errcode = '23514',
			message = 'modalidad_atribucion_id debe apuntar a vocabularios.categoria=modalidad_atribucion';
	end if;

	if new.composicion_autoria_id is not null then
		select categoria into v_composicion_categoria
		from public.vocabularios
		where termino_id = new.composicion_autoria_id;

		if v_composicion_categoria is distinct from 'composicion_autoria' then
			raise exception using
				errcode = '23514',
				message = 'composicion_autoria_id debe apuntar a vocabularios.categoria=composicion_autoria';
		end if;
	end if;

	return new;
end;
$function$
